animations.expression:
Animated.timing(iconScale, {
        toValue: TAB_PRESS_SCALE,
        duration: TAB_PRESS_HALF_DURATION,
        easing: Easing.in(Easing.ease),
        useNativeDriver: true,
      }).start

Animated.timing(iconScale, {
          toValue: 1,
          duration: TAB_PRESS_HALF_DURATION,
          easing: Easing.out(Easing.ease),
          useNativeDriver: true,
        }).start

Animated.timing(progress, {
        toValue: 1,
        duration: resolvedEnterDuration,
        easing: enterEasing,
        useNativeDriver: true,
      }).start

Animated.timing(progress, {
      toValue: 0,
      duration: resolvedExitDuration,
      easing: exitEasing,
      useNativeDriver: true,
    }).start

Animated.timing(progress, {
      toValue: checked ? 1 : 0,
      duration: 120,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: true,
    }).start

Animated.timing(allDayHeight, {
      toValue: targetAllDayHeight,
      duration: 100,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    }).start

Animated.timing(transitionProgress, {
          toValue: 1,
          duration: PROGRAMMATIC_MONTH_ANIMATION_MS,
          easing: accelerateDecelerate,
          useNativeDriver: true,
        }).start

Animated.parallel(
      rowOffsets.current.map((value, index) => Animated.timing(value, {
        toValue: targets[index] ?? 0,
        duration: ROW_ANIMATION_MS,
        easing: accelerateDecelerate,
        useNativeDriver: true,
      })),
    ).start

Animated.timing(layoutHeight, {
      toValue: datePanelHeight,
      duration: DATE_HEIGHT_ANIMATION_MS,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    }).start

Animated.timing(progress, {
        toValue: target,
        duration: Math.max(1, Math.round(OPEN_ANIMATION_MS * Math.abs(target - current))),
        easing: accelerateDecelerate,
        useNativeDriver: true,
      }).start

Animated.parallel([
      Animated.timing(pickerTransition, {
        toValue: target,
        duration: PICKER_TRANSITION_MS,
        easing: Easing.inOut(Easing.ease),
        useNativeDriver: false,
      }),
      Animated.timing(layoutHeight, {
        toValue: nextMode === 'yearMonth' ? yearMonthPanelHeight : datePanelHeight,
        duration: DATE_HEIGHT_ANIMATION_MS,
        easing: Easing.inOut(Easing.ease),
        useNativeDriver: false,
      }),
    ]).start

Animated.timing(progress, {
      toValue: 1,
      duration: Motion.standard,
      useNativeDriver: true,
    }).start

Animated.timing(progress, {
      toValue: 0,
      duration: Motion.fast,
      useNativeDriver: true,
    }).start

Animated.timing(progress, {
      toValue: on ? 1 : 0,
      duration: FEISHU_MOTION.fabSegment,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: true,
    }).start
